import 'package:flutter/material.dart';
import 'package:flutter/semantics.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

import '../../../../core/design_tokens.dart';
import '../../../../core/resource.dart';
import '../../../../core/widgets/app_text_field.dart';
import '../../../../core/widgets/avatar.dart';
import '../../../../core/widgets/back_arrow_header.dart';
import '../../../dashboard/domain/entities/dashboard_aggregate.dart';
import '../../../dashboard/presentation/cubit/dashboard_cubit.dart';
import '../../../dashboard/presentation/cubit/dashboard_narrative_cubit.dart';
import '../../../dashboard/presentation/widgets/dashboard_chart_section.dart';
import '../cubit/account_settings_cubit.dart';

/// Tela 6 — Configurações, Story 2.4's real build (Acceptance Criteria:
/// "shows only the biometric toggle — minimal, Epic 8 extends it, never
/// rebuilds it") extended by spec-8-1 with the "Sua evolução" chart
/// section below the toggle, and by spec-8-2 with its independent AI
/// narrative fetch. Replaces the former `ConfiguracoesPlaceholderScreen`.
class AccountSettingsScreen extends StatefulWidget {
  const AccountSettingsScreen({
    required this.cubit,
    required this.dashboardCubit,
    required this.narrativeCubit,
    super.key,
  });

  final AccountSettingsCubit cubit;

  /// spec-8-1 — the "Sua evolução" chart section's own cubit, a DI
  /// `lazySingleton` like [cubit] (Code Map); this `StatefulWidget` never
  /// closes it either, same rationale [cubit]'s own doc already gives.
  final DashboardCubit dashboardCubit;

  /// spec-8-2 — the chart section's own independent AI narrative fetch, a
  /// second DI `lazySingleton` like [dashboardCubit] above (Boundaries:
  /// "two independent fetches fired in parallel, neither awaiting the
  /// other").
  final DashboardNarrativeCubit narrativeCubit;

  @override
  State<AccountSettingsScreen> createState() => _AccountSettingsScreenState();
}

class _AccountSettingsScreenState extends State<AccountSettingsScreen> {
  /// spec-8-3 — the inline name field's own controller. Its text is kept
  /// in sync with `AccountSettingsState.nameDraft` only when entering edit
  /// mode (the `BlocListener` below); while editing, the field's own
  /// `onChanged` is this screen's single source for both the controller's
  /// displayed text and the cubit's `nameDraft`.
  late final TextEditingController _nameController;

  @override
  void initState() {
    super.initState();
    // Review finding: `widget.cubit` is a DI singleton that outlives this
    // `State` — if it's already mid-edit on mount (e.g. the user left
    // Configurações via the back arrow, which never calls
    // `cancelEditingName`, then reopened it), a fresh, empty controller
    // would otherwise desync from the retained `nameDraft`: the field
    // shows blank while `confirmEditingName()` would silently save the
    // old, invisible draft.
    final cubitState = widget.cubit.state;
    _nameController = TextEditingController(
      text: cubitState.isEditingName ? cubitState.nameDraft : '',
    );
    if (cubitState.isEditingName) {
      _nameController.selection = TextSelection.collapsed(
        offset: _nameController.text.length,
      );
    }
    // Review finding: clears a leftover error from a previous visit's
    // failed toggle — this cubit is a DI singleton, so without this a
    // stale message would still be showing on an unrelated later visit.
    widget.cubit.clearStaleError();
    // Boundaries: "`AccountSettingsScreen.initState` calls
    // `dashboardCubit.load()` unconditionally... so every open is a live
    // fetch, never the singleton's stale state" (FR-09: "computed on
    // demand, never stale").
    widget.dashboardCubit.load();
    // spec-8-2 — fired alongside the call above, neither awaiting the
    // other (Boundaries: "two independent fetches fired in parallel").
    widget.narrativeCubit.load();
  }

  @override
  void dispose() {
    _nameController.dispose();
    super.dispose();
  }

  /// spec-8-3 — caller derives initials from the display name (Boundaries):
  /// first letter of the first word plus first letter of the last word (a
  /// single-word name yields one letter) — `Avatar` itself only renders
  /// whatever it's given, uppercased.
  ///
  /// Code-review patch: extracts each initial via `Characters.first`
  /// (Unicode grapheme-cluster aware), not `String.substring(0, 1)` —
  /// `substring` slices by UTF-16 code unit, which would split an astral-
  /// plane character (e.g. an emoji) that starts a word into an unpaired
  /// surrogate half.
  String _initialsFor(String name) {
    final words = name
        .trim()
        .split(RegExp(r'\s+'))
        .where((w) => w.isNotEmpty)
        .toList();
    if (words.isEmpty) {
      return '';
    }
    final first = words.first.characters.first;
    if (words.length == 1) {
      return first;
    }
    final last = words.last.characters.first;
    return '$first$last';
  }

  /// spec-8-3 — the profile header: 52dp avatar + name/email, the pencil-
  /// becomes-check inline name edit (Intent/Boundaries). Built from
  /// `AccountSettingsState` directly, same "cubit is the single source"
  /// convention the rest of this screen already follows.
  Widget _buildNameRow(BuildContext context, AccountSettingsState state) {
    final cubit = context.read<AccountSettingsCubit>();
    if (!state.isEditingName) {
      return Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Flexible(
            child: Text(
              state.displayName,
              style: DesignTokens.textTitleSm.copyWith(
                color: DesignTokens.colorTextPrimary,
              ),
              // Code-review patch: the backend allows a displayName up to
              // 80 characters — without this, a long name wraps to
              // multiple lines inside this `Flexible`, misaligning against
              // the fixed-size pencil icon beside it.
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
          ),
          const SizedBox(width: DesignTokens.spacingSm),
          Semantics(
            button: true,
            label: 'Editar nome',
            excludeSemantics: true,
            child: InkWell(
              onTap: cubit.startEditingName,
              child: ConstrainedBox(
                constraints: const BoxConstraints(
                  minWidth: DesignTokens.insertionModalTapTargetMin,
                  minHeight: DesignTokens.insertionModalTapTargetMin,
                ),
                child: const Icon(
                  Icons.edit,
                  size: DesignTokens.dialogIconSize,
                  color: DesignTokens.colorPrimary,
                ),
              ),
            ),
          ),
        ],
      );
    }

    // Boundaries: "Field + check icon in one TapRegion(onTapOutside:
    // cancelEditingName)" — a tap anywhere outside this field+icon pair
    // reverts the unconfirmed edit, no PATCH sent.
    return TapRegion(
      onTapOutside: (_) => cubit.cancelEditingName(),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Expanded(
            child: AppTextField(
              controller: _nameController,
              errorText: state.nameErrorMessage,
              onChanged: cubit.updateNameDraft,
            ),
          ),
          const SizedBox(width: DesignTokens.spacingSm),
          if (state.isSavingName)
            const SizedBox(
              width: DesignTokens.accountSettingsSavingIndicatorSize,
              height: DesignTokens.accountSettingsSavingIndicatorSize,
              child: CircularProgressIndicator(
                strokeWidth:
                    DesignTokens.accountSettingsSavingIndicatorStrokeWidth,
                color: DesignTokens.colorAccent,
              ),
            )
          else
            Semantics(
              button: true,
              label: 'Salvar nome',
              excludeSemantics: true,
              child: InkWell(
                onTap: cubit.confirmEditingName,
                child: ConstrainedBox(
                  constraints: const BoxConstraints(
                    minWidth: DesignTokens.insertionModalTapTargetMin,
                    minHeight: DesignTokens.insertionModalTapTargetMin,
                  ),
                  child: const Icon(
                    Icons.check,
                    size: DesignTokens.dialogIconSize,
                    color: DesignTokens.colorPrimary,
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }

  Widget _buildProfileHeader(BuildContext context, AccountSettingsState state) {
    return Row(
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        Avatar(
          size: AvatarSize.large,
          initials: _initialsFor(state.displayName),
        ),
        const SizedBox(width: DesignTokens.spacingMd),
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              _buildNameRow(context, state),
              const SizedBox(height: DesignTokens.spacingXs),
              Text(
                state.email,
                style: DesignTokens.dashboardNarrativeTextStyle.copyWith(
                  color: DesignTokens.colorTextSecondary,
                ),
                // Review finding: same overflow fix as the adjacent name
                // `Text` above — a long e-mail would otherwise wrap to
                // multiple lines and misalign this row.
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
              ),
            ],
          ),
        ),
      ],
    );
  }

  // Review finding: mirrors `vault_lock_screen.dart`'s own `_announce` —
  // VoiceOver (this app is iOS-only) doesn't reliably treat a live-region
  // subtree update as an announcement on its own, so a failed/reverted
  // toggle is spoken explicitly here instead.
  Future<void> _announce(String message) async {
    if (!mounted) {
      return;
    }
    await SemanticsService.sendAnnouncement(
      View.of(context),
      message,
      TextDirection.ltr,
    );
  }

  @override
  Widget build(BuildContext context) {
    return MultiBlocProvider(
      providers: [
        BlocProvider.value(value: widget.cubit),
        // spec-8-1 — makes `DashboardCubit` available to
        // `DashboardChartSection` below, same two-cubit convention
        // `MeusRegistrosScreen` already uses for its own `cubit`/
        // `searchCubit` pair.
        BlocProvider.value(value: widget.dashboardCubit),
        // spec-8-2 — makes `DashboardNarrativeCubit` available to
        // `DashboardChartSection`'s own narrative section, same
        // convention as `dashboardCubit` above.
        BlocProvider.value(value: widget.narrativeCubit),
      ],
      child: Scaffold(
        backgroundColor: DesignTokens.colorSurfaceBg,
        body: Column(
          children: [
            const BackArrowHeader(title: 'Configurações'),
            // spec-8-1 — now `Expanded` + scrollable: the toggle alone
            // always fit unscrolled, but the chart section below it can
            // grow past the available height on a shorter device/larger
            // text scale (Design Notes: "decide and proceed" — neither
            // `prototype-extract.md` nor the frozen spec says whether this
            // screen scrolls).
            Expanded(
              child: SingleChildScrollView(
                padding: DesignTokens.screenPadding,
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    // spec-8-3 — Code Map: "header is the first scroll-
                    // Column child, above the toggle".
                    MultiBlocListener(
                      listeners: [
                        // Syncs the field's controller only at the moment
                        // editing starts — while editing, the field's own
                        // `onChanged` (-> `updateNameDraft`) is this
                        // screen's single source for both the
                        // controller's displayed text and the cubit's own
                        // `nameDraft`.
                        BlocListener<
                          AccountSettingsCubit,
                          AccountSettingsState
                        >(
                          listenWhen: (previous, current) =>
                              !previous.isEditingName && current.isEditingName,
                          listener: (context, state) {
                            _nameController.text = state.nameDraft;
                            _nameController.selection = TextSelection.collapsed(
                              offset: _nameController.text.length,
                            );
                          },
                        ),
                        // Boundaries: "`_announce` fires on a save
                        // failure, same `BlocListener` convention as the
                        // toggle's error".
                        BlocListener<
                          AccountSettingsCubit,
                          AccountSettingsState
                        >(
                          listenWhen: (previous, current) =>
                              current.nameErrorMessage != null &&
                              current.nameErrorMessage !=
                                  previous.nameErrorMessage,
                          listener: (context, state) {
                            _announce(state.nameErrorMessage!);
                          },
                        ),
                      ],
                      child:
                          BlocBuilder<
                            AccountSettingsCubit,
                            AccountSettingsState
                          >(
                            builder: (context, state) =>
                                _buildProfileHeader(context, state),
                          ),
                    ),
                    const SizedBox(height: DesignTokens.spacingXl),
                    BlocConsumer<AccountSettingsCubit, AccountSettingsState>(
                      listener: (context, state) {
                        if (state.errorMessage != null) {
                          _announce(state.errorMessage!);
                        }
                      },
                      builder: (context, state) {
                        return Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            MergeSemantics(
                              child: Semantics(
                                label: 'Entrar com biometria',
                                child: Row(
                                  children: [
                                    Expanded(
                                      child: ExcludeSemantics(
                                        child: Text(
                                          'Entrar com biometria',
                                          style: DesignTokens.textBodyLg
                                              .copyWith(
                                                color: DesignTokens
                                                    .colorTextPrimary,
                                              ),
                                        ),
                                      ),
                                    ),
                                    if (state.isSaving) ...[
                                      const SizedBox(
                                        width: DesignTokens
                                            .accountSettingsSavingIndicatorSize,
                                        height: DesignTokens
                                            .accountSettingsSavingIndicatorSize,
                                        child: CircularProgressIndicator(
                                          strokeWidth: DesignTokens
                                              .accountSettingsSavingIndicatorStrokeWidth,
                                          color: DesignTokens.colorAccent,
                                        ),
                                      ),
                                      const SizedBox(
                                        width: DesignTokens.spacingSm,
                                      ),
                                    ],
                                    Switch(
                                      value: state.biometricEnabled,
                                      // Boundaries: "no new tokens" — reuses
                                      // `colorAccent` (Design Notes).
                                      activeThumbColor:
                                          DesignTokens.colorAccent,
                                      // Review finding: `null` while a
                                      // toggle is already in flight
                                      // (`state.isSaving`) — a disabled
                                      // `Switch` can't be tapped again, so a
                                      // double-tap can never start a
                                      // second, overlapping
                                      // `toggleBiometric` call.
                                      onChanged: state.isSaving
                                          ? null
                                          : (value) => context
                                                .read<AccountSettingsCubit>()
                                                .toggleBiometric(value),
                                    ),
                                  ],
                                ),
                              ),
                            ),
                            if (state.errorMessage != null) ...[
                              const SizedBox(height: DesignTokens.spacingSm),
                              Text(
                                state.errorMessage!,
                                style: DesignTokens.textBodyMd.copyWith(
                                  color: DesignTokens.colorError,
                                ),
                              ),
                            ],
                          ],
                        );
                      },
                    ),
                    // spec-8-1 — "Sua evolução", sibling to the biometric
                    // toggle section above (Code Map: "insert chart as
                    // sibling Column child").
                    const SizedBox(height: DesignTokens.spacingXl),
                    // Review finding: unlike the biometric toggle's own
                    // `BlocConsumer` above, the chart section previously
                    // never announced its own fetch failures to
                    // VoiceOver — a `ResourceError` only ever showed as
                    // silent inline text. Reuses the same [_announce]
                    // this `State` already uses for the toggle's error,
                    // same "VoiceOver doesn't reliably treat a live-region
                    // update as an announcement on its own" rationale.
                    MultiBlocListener(
                      listeners: [
                        BlocListener<
                          DashboardCubit,
                          Resource<DashboardAggregate>
                        >(
                          listener: (context, state) {
                            if (state is ResourceError<DashboardAggregate>) {
                              _announce(state.failure.message);
                            }
                          },
                        ),
                        // Spec Change Log (spec-8-2 amendment) — the
                        // original unconditional version of this listener
                        // could speak a narrative-failed announcement for
                        // a user whose screen never shows the narrative
                        // section at all (0/1/mid-range counts), in
                        // tension with the adjacent frozen "Never: show
                        // narrative text or its error for 0/1-count
                        // states" line. Gated on `DashboardCubit`'s own
                        // *current* state — read directly via
                        // `context.read`, never merged with this
                        // `Resource<String>` into one state object (the
                        // "Never: couple the two Resources" line is
                        // unaffected) — and announces the same fixed copy
                        // the narrative section itself renders
                        // (`DashboardChartSection.narrativeUnavailableMessage`)
                        // rather than the raw, unsanitized `Failure.
                        // message`, so VoiceOver and sighted users hear/
                        // read the same wording for the same failure.
                        BlocListener<DashboardNarrativeCubit, Resource<String>>(
                          listener: (context, state) {
                            if (state is! ResourceError<String>) {
                              return;
                            }
                            final dashboardState = context
                                .read<DashboardCubit>()
                                .state;
                            if (dashboardState
                                    is ResourceData<DashboardAggregate> &&
                                dashboardState.data.totalCount > 30) {
                              _announce(
                                DashboardChartSection
                                    .narrativeUnavailableMessage,
                              );
                            }
                          },
                        ),
                        // Review finding: the listener above only reads
                        // `DashboardNarrativeCubit`'s *current* state at
                        // the instant `DashboardCubit` itself transitions
                        // past 30 — but the two fetches race independently
                        // (Boundaries: "neither awaiting the other"), so
                        // the narrative can just as easily resolve to
                        // `ResourceError` *before* the aggregate ever
                        // reaches `totalCount > 30`. Without this sibling
                        // listener that ordering silently drops the
                        // announcement forever for that screen-open, even
                        // though the error text later becomes visible once
                        // the aggregate resolves — the exact VoiceOver/
                        // on-screen desync the amendment above exists to
                        // prevent. Same read-only, ungated-state check as
                        // the listener above, just triggered from the
                        // other cubit's own transition.
                        BlocListener<
                          DashboardCubit,
                          Resource<DashboardAggregate>
                        >(
                          // Review finding: without this, every later
                          // `DashboardCubit` emission with `totalCount >
                          // 30` (e.g. each further `confirmedWrites`-
                          // triggered reload) re-ran the listener and
                          // re-announced the same unchanged narrative
                          // error — not just the one missed transition
                          // this listener exists to catch. Only fires on
                          // the transition *into* `totalCount > 30`.
                          listenWhen: (previous, current) =>
                              !(previous is ResourceData<DashboardAggregate> &&
                                  previous.data.totalCount > 30) &&
                              current is ResourceData<DashboardAggregate> &&
                              current.data.totalCount > 30,
                          listener: (context, state) {
                            if (state is! ResourceData<DashboardAggregate> ||
                                state.data.totalCount <= 30) {
                              return;
                            }
                            final narrativeState = context
                                .read<DashboardNarrativeCubit>()
                                .state;
                            if (narrativeState is ResourceError<String>) {
                              _announce(
                                DashboardChartSection
                                    .narrativeUnavailableMessage,
                              );
                            }
                          },
                        ),
                      ],
                      child: const DashboardChartSection(),
                    ),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'dart:async';

import 'package:flutter_bloc/flutter_bloc.dart';

import '../../domain/repositories/account_settings_repository.dart';

/// Drives [AccountSettingsScreen]: just the one toggle's current value
/// (mirrored straight from [AccountSettingsRepository.biometricEnabledStream]
/// — the repository is the single source of truth, Boundaries) plus an
/// inline error message for a failed toggle.
class AccountSettingsState {
  const AccountSettingsState({
    required this.biometricEnabled,
    this.errorMessage,
    this.isSaving = false,
    this.displayName = '',
    this.email = '',
    this.isEditingName = false,
    this.nameDraft = '',
    this.isSavingName = false,
    this.nameErrorMessage,
  });

  final bool biometricEnabled;

  /// Set only once [AccountSettingsCubit.toggleBiometric]'s own PATCH call
  /// fails — the switch itself has already reverted via the repository's
  /// own stream by the time this is shown (I/O matrix: "Toggle fails ->
  /// switch reverts ... Failure.message shown inline").
  final String? errorMessage;

  /// Review finding: `true` for the duration of one [toggleBiometric] call
  /// — `account_settings_screen.dart` disables the `Switch` while this is
  /// `true`, so a double-tap can never start a second, overlapping
  /// `setBiometricEnabled` call in the first place (the repository's own
  /// generation guard is the backstop for every other overlap this can't
  /// prevent, e.g. a boot fetch racing a toggle).
  final bool isSaving;

  /// spec-8-3 — the profile name shown in display mode, read from
  /// `AccountSettingsRepository.currentDisplayName` at construction
  /// (Boundaries), then kept in sync by [AccountSettingsCubit.
  /// confirmEditingName]'s own success branch — never re-read from the
  /// repository afterwards.
  final String displayName;

  /// spec-8-3 — the account e-mail, read the same way as [displayName] and
  /// never written anywhere (not editable — "email is rejected").
  final String email;

  /// spec-8-3 — `true` while the name is in its inline-editable form (the
  /// pencil icon has become a check). Boundaries: "startEditingName()
  /// (draft = current name)".
  final bool isEditingName;

  /// spec-8-3 — the in-progress edit's own text, separate from
  /// [displayName] until [AccountSettingsCubit.confirmEditingName] commits
  /// it. Kept exactly as typed (not trimmed) so a failed save redisplays
  /// the same text the user left in the field (Boundaries: "draft kept").
  final String nameDraft;

  /// spec-8-3 — `true` for the duration of one
  /// [AccountSettingsCubit.confirmEditingName] PATCH call. Mirrors
  /// [isSaving]'s own role for the biometric toggle, kept as its own field
  /// (Boundaries: "never: merging name-edit into the toggle's own state").
  final bool isSavingName;

  /// spec-8-3 — set only once [AccountSettingsCubit.confirmEditingName]'s
  /// own PATCH call fails; the field stays editable with [nameDraft]
  /// unchanged (I/O matrix: "Failure -> stays editing, inline error, draft
  /// kept").
  final String? nameErrorMessage;

  AccountSettingsState copyWith({
    bool? biometricEnabled,
    String? errorMessage,
    bool clearErrorMessage = false,
    bool? isSaving,
    String? displayName,
    String? email,
    bool? isEditingName,
    String? nameDraft,
    bool? isSavingName,
    String? nameErrorMessage,
    bool clearNameErrorMessage = false,
  }) {
    return AccountSettingsState(
      biometricEnabled: biometricEnabled ?? this.biometricEnabled,
      errorMessage: clearErrorMessage
          ? null
          : (errorMessage ?? this.errorMessage),
      isSaving: isSaving ?? this.isSaving,
      displayName: displayName ?? this.displayName,
      email: email ?? this.email,
      isEditingName: isEditingName ?? this.isEditingName,
      nameDraft: nameDraft ?? this.nameDraft,
      isSavingName: isSavingName ?? this.isSavingName,
      nameErrorMessage: clearNameErrorMessage
          ? null
          : (nameErrorMessage ?? this.nameErrorMessage),
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is AccountSettingsState &&
          other.biometricEnabled == biometricEnabled &&
          other.errorMessage == errorMessage &&
          other.isSaving == isSaving &&
          other.displayName == displayName &&
          other.email == email &&
          other.isEditingName == isEditingName &&
          other.nameDraft == nameDraft &&
          other.isSavingName == isSavingName &&
          other.nameErrorMessage == nameErrorMessage);

  @override
  int get hashCode => Object.hash(
    biometricEnabled,
    errorMessage,
    isSaving,
    displayName,
    email,
    isEditingName,
    nameDraft,
    isSavingName,
    nameErrorMessage,
  );

  @override
  String toString() =>
      'AccountSettingsState(biometricEnabled: $biometricEnabled, '
      'errorMessage: $errorMessage, isSaving: $isSaving, '
      'displayName: $displayName, email: $email, '
      'isEditingName: $isEditingName, nameDraft: $nameDraft, '
      'isSavingName: $isSavingName, nameErrorMessage: $nameErrorMessage)';
}

/// Calls [AccountSettingsRepository] directly (no use-case — same small-
/// scope rationale `AuthCubit`'s own doc gives). [toggleBiometric] is the
/// I/O matrix's optimistic flip/revert, end to end: the repository itself
/// flips [AccountSettingsRepository.currentBiometricEnabled] immediately
/// and emits it on [AccountSettingsRepository.biometricEnabledStream] —
/// this cubit only mirrors that stream into its own [AccountSettingsState]
/// (subscribed once, at construction) and separately layers the
/// toggle-failure error message on top.
class AccountSettingsCubit extends Cubit<AccountSettingsState> {
  AccountSettingsCubit(this._repository)
    : super(
        AccountSettingsState(
          biometricEnabled: _repository.currentBiometricEnabled,
          // spec-8-3 — read once, at construction (Boundaries); never
          // re-read from the repository afterwards.
          displayName: _repository.currentDisplayName,
          email: _repository.currentEmail,
        ),
      ) {
    _subscription = _repository.biometricEnabledStream.listen((value) {
      // Review finding: `biometricEnabledStream`'s first delivery always
      // replays the exact same value the constructor above just read
      // synchronously — without this check, that replay was a redundant
      // duplicate emission (not skipped by `Cubit`'s own equal-state dedup,
      // which only applies once something has already been emitted),
      // forcing one pointless extra rebuild right after every screen mount.
      if (value == state.biometricEnabled) {
        return;
      }
      emit(state.copyWith(biometricEnabled: value));
    });
  }

  final AccountSettingsRepository _repository;
  late final StreamSubscription<bool> _subscription;

  Future<void> toggleBiometric(bool value) async {
    emit(state.copyWith(clearErrorMessage: true, isSaving: true));
    final result = await _repository.setBiometricEnabled(value);
    // Review finding: this cubit is a `get_it` lazy singleton with
    // `dispose: (cubit) => cubit.close()` — if `close()` runs while the
    // `await` above is still pending (e.g. `resetCoreDependencies()`
    // during a logout, once Epic 8 implements one), `emit()` below would
    // otherwise throw a `StateError` ("Cannot emit new states after
    // calling close"), unlike the repository-layer `_emit` methods in this
    // codebase, which already guard against the equivalent race.
    if (isClosed) {
      return;
    }
    result.match((failure) {
      // Review finding: a superseded call's `Left` is an internal
      // control-flow signal (`AccountSettingsRepository.
      // supersededMessage`), not a real error — the winning call already
      // settled the value correctly, so nothing should be shown; showing
      // `failure.message` unconditionally leaked that raw, English,
      // internal string into this otherwise fully Portuguese screen.
      if (failure.message == AccountSettingsRepository.supersededMessage) {
        emit(state.copyWith(isSaving: false));
        return;
      }
      emit(state.copyWith(errorMessage: failure.message, isSaving: false));
    }, (_) => emit(state.copyWith(isSaving: false)));
  }

  /// Review finding: [errorMessage] previously cleared only at the start of
  /// the *next* [toggleBiometric] call — since this cubit is a DI
  /// singleton that outlives any single Configurações visit, a failed
  /// toggle's error text would otherwise still be showing if the user
  /// left the screen and came back later with no new attempt made.
  /// `account_settings_screen.dart` calls this once, on mount, same
  /// "stale message must not linger unchanged" fix already applied to
  /// `vault_lock_screen.dart`'s own PIN-mismatch error, just anchored to
  /// screen-entry instead of attempt-start.
  void clearStaleError() {
    if (state.errorMessage != null) {
      emit(state.copyWith(clearErrorMessage: true));
    }
  }

  /// spec-8-3 — tapping the pencil icon (I/O matrix: "Tap pencil ->
  /// `isEditingName: false` -> Field replaces name, draft = current, icon
  /// -> check"). Also clears any leftover [AccountSettingsState.
  /// nameErrorMessage] from a previous failed attempt.
  void startEditingName() {
    emit(
      state.copyWith(
        isEditingName: true,
        nameDraft: state.displayName,
        clearNameErrorMessage: true,
      ),
    );
  }

  /// spec-8-3 — mirrors the field's own `onChanged`, kept as the single
  /// source [confirmEditingName] reads from.
  void updateNameDraft(String value) {
    emit(state.copyWith(nameDraft: value));
  }

  /// spec-8-3 — I/O matrix: "Tap away, not saving -> Reverts, draft
  /// discarded, no PATCH" / "Tap away, saving -> No-op, save completes".
  /// A no-op while [AccountSettingsState.isSavingName] (Boundaries) — the
  /// in-flight [confirmEditingName] call owns the eventual transition back
  /// to display mode.
  void cancelEditingName() {
    if (state.isSavingName) {
      return;
    }
    emit(state.copyWith(isEditingName: false, clearNameErrorMessage: true));
  }

  /// spec-8-3 — tapping the check icon. Trims [AccountSettingsState.
  /// nameDraft] only for the empty/unchanged comparison and the PATCH
  /// payload itself; an empty or unchanged draft reverts immediately with
  /// no PATCH (I/O matrix). Otherwise awaits
  /// `AccountSettingsRepository.setDisplayName` (not optimistic,
  /// Boundaries) — success reverts to display mode showing the new name;
  /// failure stays in edit mode with the draft kept and an inline error.
  Future<void> confirmEditingName() async {
    final trimmed = state.nameDraft.trim();
    if (trimmed.isEmpty || trimmed == state.displayName) {
      emit(state.copyWith(isEditingName: false, clearNameErrorMessage: true));
      return;
    }
    emit(state.copyWith(isSavingName: true, clearNameErrorMessage: true));
    final result = await _repository.setDisplayName(trimmed);
    // Same close()-race guard as toggleBiometric's own.
    if (isClosed) {
      return;
    }
    result.match(
      (failure) {
        // Same superseded-message filtering convention as toggleBiometric's
        // own failure branch — an internal control-flow signal, not a real
        // error to show.
        if (failure.message == AccountSettingsRepository.supersededMessage) {
          emit(state.copyWith(isSavingName: false));
          return;
        }
        emit(
          state.copyWith(
            isSavingName: false,
            nameErrorMessage: failure.message,
          ),
        );
      },
      (_) {
        // Review finding: reads the repository's own echoed value (set
        // from `dto.displayName` in `setDisplayName`'s success branch),
        // not the locally-sent `trimmed` string — any backend-side
        // normalization (trimming, casing, etc.) must reach this state,
        // the one place the user actually sees the name, not just the
        // repository's own internal cache.
        emit(
          state.copyWith(
            isEditingName: false,
            isSavingName: false,
            displayName: _repository.currentDisplayName,
            clearNameErrorMessage: true,
          ),
        );
      },
    );
  }

  @override
  Future<void> close() async {
    await _subscription.cancel();
    return super.close();
  }
}

