341	    cleanup: () async {
342	      // Review fix: guards `isClosed` too, not just `isRegistered` — a
343	      // double `close()` on an already-closed Cubit never resolves
344	      // inside flutter_test's fake-async zone, freezing the suite (the
345	      // exact hazard `app_drawer_test.dart`'s/`main_test.dart`'s own
346	      // tearDown already guards against).
347	      if (sl.isRegistered<ChatCubit>() && !sl<ChatCubit>().isClosed) {
348	        await sl<ChatCubit>().close();
349	      }
350	    },
351	  );
