36	  void queueErrorResponse(String code, String message) {
37	    final status = switch (code) {
38	      'VALIDATION_ERROR' => 400,
39	      'NETWORK_TIMEOUT' => 504,
40	      _ => 500,
41	    };
42	    queueJsonResponse(status, {
43	      'code': code,
44	      'message': message,
45	      'retryable': RetryInterceptor.retryableCodes.contains(code),
