49	  @override
50	  Future<ResponseBody> fetch(
51	    RequestOptions options,
52	    Stream<Uint8List>? requestStream,
53	    Future<void>? cancelFuture,
54	  ) async {
55	    requests.add(options);
56	    if (_queue.isEmpty) {
57	      throw StateError(
58	        'No queued response for ${options.method} ${options.path}',
59	      );
60	    }
61	    final next = _queue.removeAt(0);
62	    return ResponseBody.fromString(
63	      jsonEncode(next.body),
64	      next.statusCode,
65	      headers: {
66	        Headers.contentTypeHeader: [Headers.jsonContentType],
67	      },
68	    );
69	  }
